// SAMPLE DATA ONLY. Every practice, person, and address below is fictional.
// Contacts use .example domains so nothing can ever reach a real inbox.
// In production this step would query the NPI Registry (taxonomy codes for
// internal medicine, family medicine, and preventive medicine in NYC zip codes)
// and the CMS provider directory, then enrich each practice from its website
// and public social profiles. Here we generate 75 practices with a fixed seed
// so every run produces the exact same list.

function mulberry32(a) {
  return function () {
    a |= 0; a = (a + 0x6D2B79F5) | 0;
    let t = Math.imul(a ^ (a >>> 15), 1 | a);
    t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t;
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}
const rand = mulberry32(20261031);
const pick = (arr) => arr[Math.floor(rand() * arr.length)];
const shuffle = (arr) => {
  const a = arr.slice();
  for (let i = a.length - 1; i > 0; i--) {
    const j = Math.floor(rand() * (i + 1));
    const t = a[i]; a[i] = a[j]; a[j] = t;
  }
  return a;
};

const places = [
  ['Hudson', 'Manhattan'], ['Gramercy', 'Manhattan'], ['Tribeca', 'Manhattan'],
  ['Flatiron', 'Manhattan'], ['Lenox', 'Manhattan'], ['Sutton', 'Manhattan'],
  ['Carnegie', 'Manhattan'], ['Madison', 'Manhattan'], ['Noho', 'Manhattan'],
  ['Murray Hill', 'Manhattan'], ['Riverside', 'Manhattan'], ['Chelsea', 'Manhattan'],
  ['Park Slope', 'Brooklyn'], ['Williamsburg', 'Brooklyn'], ['Dumbo', 'Brooklyn'],
  ['Fort Greene', 'Brooklyn'], ['Cobble Hill', 'Brooklyn'], ['Bay Ridge', 'Brooklyn'],
  ['Astoria', 'Queens'], ['Forest Hills', 'Queens'], ['Long Island City', 'Queens'],
  ['Bayside', 'Queens'], ['Riverdale', 'Bronx'], ['Pelham', 'Bronx'],
  ['St. George', 'Staten Island']
];
const kinds = [
  'Longevity Clinic', 'Concierge Medicine', 'Wellness Collective', 'Healthspan Center',
  'Vitality Medical', 'Longevity Lab', 'Integrative Health'
];
const firstNames = ['Maya', 'Daniel', 'Priya', 'Elena', 'Marcus', 'Sofia', 'Jonah', 'Aisha',
  'Ravi', 'Claire', 'Theo', 'Nadia', 'Victor', 'Leah', 'Omar', 'Hannah', 'Julian', 'Grace',
  'Samir', 'Ingrid', 'Felix', 'Rosa', 'Andre', 'Mira'];
const lastNames = ['Okafor', 'Lindqvist', 'Raman', 'Castellano', 'Brennan', 'Haddad', 'Kowalski',
  'Nakamura', 'Ferreira', 'Goldberg', 'Mensah', 'Petrov', 'Alvarez', 'Chen', 'Duarte', 'Weiss',
  'Osei', 'Moreau', 'Kapoor', 'Sullivan', 'Abrams', 'Tanaka', 'Rossi', 'Iyer'];
const pmFirst = ['Jess', 'Carla', 'Tom', 'Bianca', 'Kevin', 'Alana', 'Rob', 'Tessa', 'Luis',
  'Dana', 'Megan', 'Chris', 'Nina', 'Paul', 'Erin', 'Sam'];
const pmLast = ['Reyes', 'Murphy', 'Stein', 'Park', 'Walsh', 'Bauer', 'Lopez', 'Grant',
  'Novak', 'Price', 'Hale', 'Ortiz'];
const services = [
  'peptide therapy', 'longevity assessments', 'hormone optimization', 'NAD+ infusions',
  'metabolic health coaching', 'advanced biomarker panels', 'body composition scans',
  'sleep optimization', 'IV nutrient therapy', 'executive physicals', 'VO2 max testing',
  'continuous glucose monitoring programs'
];
const newServices = ['a GLP-1 weight program', 'VO2 max testing', 'a menopause care track',
  'full-body MRI referrals', 'a sleep optimization program', 'peptide therapy'];

const slugify = (s) => s.toLowerCase().replace(/[^a-z0-9]+/g, '');

const combos = [];
for (const p of places) for (const k of kinds) combos.push([p[0], p[1], k]);
const chosen = shuffle(combos).slice(0, 75);

const out = chosen.map((c, i) => {
  const name = c[0] + ' ' + c[2];
  const slug = slugify(name);
  const founderFirst = pick(firstNames);
  const founderLast = pick(lastNames);
  const pmF = pick(pmFirst);
  const pmL = pick(pmLast);
  const providersRoll = rand();
  const providers = providersRoll < 0.12 ? 1 : providersRoll < 0.88 ? 2 + Math.floor(rand() * 14) : 16 + Math.floor(rand() * 10);
  const growthRoll = rand();
  let growthType = 'none';
  if (growthRoll < 0.18) growthType = 'new location';
  else if (growthRoll < 0.40) growthType = 'hiring';
  else if (growthRoll < 0.62) growthType = 'new service line';
  const newService = pick(newServices);
  let growthDetail = 'No recent growth signal found';
  if (growthType === 'new location') growthDetail = 'Opened a second location in ' + pick(['Midtown', 'the Upper East Side', 'Brooklyn Heights', 'Hoboken', 'Westchester']);
  if (growthType === 'hiring') growthDetail = 'Hiring a ' + pick(['nurse practitioner', 'health coach', 'second physician', 'patient care coordinator']);
  if (growthType === 'new service line') growthDetail = 'Recently launched ' + newService;
  const svc = shuffle(services).slice(0, 2 + Math.floor(rand() * 2));
  const hasBooking = rand() < 0.62;
  const social = rand() < 0.58;
  const socialChannel = social ? pick(['Instagram', 'LinkedIn', 'Instagram and LinkedIn']) : 'none';
  const founderDirect = rand() < 0.66;
  const founderOnLinkedIn = rand() < 0.7;
  return {
    json: {
      data_label: 'SAMPLE fictional data',
      id: 'NYC-LGV-' + String(i + 1).padStart(3, '0'),
      name: name,
      slug: slug,
      borough: c[1],
      neighborhood: c[0],
      providers: providers,
      decision_maker: 'Dr. ' + founderFirst + ' ' + founderLast,
      decision_maker_role: 'Founder and Medical Director',
      founder_first: founderFirst,
      founder_last: founderLast,
      founder_email: founderFirst.toLowerCase() + '@' + slug + '.example',
      founder_direct_contact: founderDirect ? 'yes' : 'no',
      founder_on_linkedin: founderOnLinkedIn ? 'yes' : 'no',
      clinical_champion: 'Dr. ' + founderFirst + ' ' + founderLast,
      practice_manager: pmF + ' ' + pmL,
      practice_manager_first: pmF,
      contact_email: pmF.toLowerCase() + '.' + pmL.toLowerCase() + '@' + slug + '.example',
      has_online_booking: hasBooking ? 'yes' : 'no',
      active_on_social: social ? 'yes' : 'no',
      social_channel: socialChannel,
      growth_signal: growthType,
      growth_detail: growthDetail,
      new_service: growthType === 'new service line' ? newService : '',
      services: svc
    }
  };
});

return out;

// SAMPLE DATA ONLY. Scores 0 to 100 for each fictional practice.
//
// Why these weights:
// Decision access (25): at a small longevity practice the founder-physician is
//   the buyer. If we can reach them directly (a published email or an active
//   LinkedIn profile) the path to a yes is short. 15 points for a direct
//   contact, 10 for being on LinkedIn.
// Digital maturity (25): online booking and an active social presence show the
//   practice already spends money and time on patient experience. Those are the
//   practices that see patient education as part of the product. 13 for
//   booking, 12 for social.
// Growth (20): practices that are opening a location, hiring, or launching a
//   service are buying new tools right now and feel the pain of explaining new
//   things to patients. A new location scores highest because it doubles the
//   volume of patient conversations.
// Product fit (20): services like peptide therapy, hormone optimization, and
//   longevity assessments come with protocols patients must follow at home, so
//   take-home education matters most there. 8 points per high-fit service, 3
//   per other service, capped at 20.
// Size fit (10): 2 to 15 providers is the sweet spot. Solo practices rarely buy
//   software, and practices over 15 usually have a marketing team and a longer
//   procurement process.
//
// Tiers: A is 80 and up, B is 60 to 79, C is below 60.

const HIGH_FIT = ['peptide therapy', 'longevity assessments', 'hormone optimization',
  'NAD+ infusions', 'metabolic health coaching', 'advanced biomarker panels',
  'continuous glucose monitoring programs'];

return $input.all().map((item) => {
  const c = item.json;
  const decision = (c.founder_direct_contact === 'yes' ? 15 : 0) + (c.founder_on_linkedin === 'yes' ? 10 : 0);
  const digital = (c.has_online_booking === 'yes' ? 13 : 0) + (c.active_on_social === 'yes' ? 12 : 0);
  const growthMap = { 'new location': 20, 'new service line': 16, 'hiring': 14, 'none': 0 };
  const growth = growthMap[c.growth_signal] || 0;
  let fit = 0;
  for (const s of c.services) fit += HIGH_FIT.includes(s) ? 8 : 3;
  fit = Math.min(20, fit);
  let size = 2;
  if (c.providers >= 2 && c.providers <= 15) size = 10;
  else if (c.providers === 1 || c.providers <= 20) size = 5;
  const score = decision + digital + growth + fit + size;
  const tier = score >= 80 ? 'A' : score >= 60 ? 'B' : 'C';
  const signals = [];
  if (c.has_online_booking === 'yes') signals.push('online booking');
  if (c.active_on_social === 'yes') signals.push('active on ' + c.social_channel);
  if (c.growth_signal !== 'none') signals.push(c.growth_detail.toLowerCase());
  signals.push('offers ' + c.services.join(', '));
  return {
    json: Object.assign({}, c, {
      score: score,
      tier: tier,
      score_decision_access: decision,
      score_digital_maturity: digital,
      score_growth: growth,
      score_product_fit: fit,
      score_size_fit: size,
      score_breakdown: 'decision access ' + decision + '/25; digital maturity ' + digital + '/25; growth ' + growth + '/20; product fit ' + fit + '/20; size fit ' + size + '/10',
      key_signals: signals.join('; ')
    })
  };
});

// SAMPLE DATA ONLY. Builds a 6-touch, 18-day sequence for every fictional
// practice. Nothing here is sent anywhere: every message becomes a row in
