// mail nodes.
//
// Sequence logic: give before asking. The practice manager hears from us
// first because she routes what the physician sees. The founder gets a
// no-ask LinkedIn connection, then a mailed one-pager, and only sees a video
// link on day 15 after the practice has already received something useful.

const SENDER = 'Mansi';
const COMPANY = 'Longevity';

function fill(tpl, v) {
  return tpl.replace(/\{(\w+)\}/g, function (m, k) { return v[k] !== undefined ? String(v[k]) : m; });
}

const HIGH_FIT = ['peptide therapy', 'longevity assessments', 'hormone optimization',
  'NAD+ infusions', 'metabolic health coaching', 'advanced biomarker panels',
  'continuous glucose monitoring programs'];

// What patients tend to forget after a visit, by service. Used in the mailed one-pager.
const FORGET = {
  'peptide therapy': 'how to store their peptides, what time of day to inject, and which side effects are normal in the first two weeks',
  'longevity assessments': 'what each biomarker on their report actually means and which two or three changes matter most',
  'hormone optimization': 'when to take their dose relative to their next blood draw and which symptoms are worth a call',
  'NAD+ infusions': 'how to prepare for the next infusion and why the first session can feel uncomfortable',
  'metabolic health coaching': 'the specific food and movement targets they agreed to in the room',
  'advanced biomarker panels': 'which markers were flagged, why they matter, and when they will be retested',
  'body composition scans': 'what their numbers mean and what a realistic change looks like in 90 days',
  'sleep optimization': 'the exact wind-down routine and supplement timing they were given',
  'IV nutrient therapy': 'how often to come back and what to eat beforehand',
  'executive physicals': 'which follow-up referrals they still need to book',
  'VO2 max testing': 'their heart rate zones and how many minutes a week to spend in each one',
  'continuous glucose monitoring programs': 'how to read a glucose spike and which meals to test first'
};

// One line for the take-home example, by service.
const SERVICE_LINE = {
  'peptide therapy': 'If peptide therapy is part of your plan, your first supply and injection instructions come at your follow-up, so there is nothing to start today.',
  'hormone optimization': 'If we talked about hormone optimization, please do not start or stop any supplements before your follow-up, because they can change your lab picture.',
  'NAD+ infusions': 'If you are booked for NAD+ infusions, drink plenty of water the day before and eat a normal meal beforehand.',
  'metabolic health coaching': 'Your coach will reach out within a few days to set your first food and movement targets, so you do not need to plan anything yet.',
  'advanced biomarker panels': 'Some of your biomarker results take longer than others, so it is normal if a few show up a few days late.',
  'continuous glucose monitoring programs': 'If you are starting a glucose monitor, wear it for the full 14 days and log your meals in the app, even the boring ones.',
  'longevity assessments': 'Write down any questions as they come up this week. Patients who bring a short list get a lot more out of their results visit.'
};

// Short names that read naturally in a sentence like "your peptide patients".
const SHORT = {
  'peptide therapy': 'peptide therapy',
  'longevity assessments': 'longevity assessment',
  'hormone optimization': 'hormone optimization',
  'NAD+ infusions': 'NAD+ infusion',
  'metabolic health coaching': 'metabolic health',
  'advanced biomarker panels': 'biomarker panel',
  'body composition scans': 'body composition',
  'sleep optimization': 'sleep optimization',
  'IV nutrient therapy': 'IV therapy',
  'executive physicals': 'executive physical',
  'VO2 max testing': 'VO2 max',
  'continuous glucose monitoring programs': 'glucose monitoring'
};

function primaryService(c) {
  if (c.new_service && HIGH_FIT.includes(c.new_service)) return c.new_service;
  for (const s of c.services) if (HIGH_FIT.includes(s)) return s;
  return c.services[0];
}

function observation(c) {
  if (c.growth_signal === 'new location') return 'that you recently ' + c.growth_detail.charAt(0).toLowerCase() + c.growth_detail.slice(1) + ', which is a big step';
  if (c.growth_signal === 'hiring') return 'that you are ' + c.growth_detail.charAt(0).toLowerCase() + c.growth_detail.slice(1) + ', so it sounds like the patient list is growing';
  if (c.growth_signal === 'new service line') return 'that you just launched ' + c.new_service;
  if (c.has_online_booking === 'yes') return 'that new patients can book online, which tells me you put real thought into how the first visit feels';
  if (c.active_on_social === 'yes') return 'that you post regularly on ' + c.social_channel + ' about ' + primaryService(c) + ', which is more than most practices do'
  return 'that you offer ' + c.services.join(' and ');
}

function linkedinHook(c) {
  if (c.growth_signal === 'new location') return 'Congrats on the new location.';
  if (c.growth_signal === 'hiring') return 'Saw you are growing the team, which is great to see.';
  if (c.growth_signal === 'new service line') return 'Saw you just added ' + c.new_service + '.';
  if (c.active_on_social === 'yes') return 'I have enjoyed your posts about ' + primaryService(c) + '.';
  return 'I like how ' + c.name + ' approaches ' + primaryService(c) + ' and wanted to say hello.';
}

function closeContext(c) {
  if (c.growth_signal === 'new location') return 'as the new location gets busier';
  if (c.growth_signal === 'hiring') return 'once the new hire is settled in';
  if (c.growth_signal === 'new service line') return 'as ' + c.new_service + ' picks up';
  return 'down the road';
}

const D1_SUBJECTS = [
  'Quick question about your {service} patients',
  'Who handles patient take-home material at {name}?',
  'A question for the {name} team'
];

const D1 = 'Hi {pm},\n\nI was looking at {name} and noticed {obs}. Quick question for you: who on your team owns the material patients take home after a visit? Is that you, Dr. {last}, or someone else?\n\nI ask because I put together a one-page example of a take-home sheet for {service} patients. It is the kind of thing that cuts down on the follow-up calls your front desk gets in the first week after a visit. There is no pitch attached and nothing to sign up for. If it sounds useful, just reply and I will send it over.\n\nThanks,\n{sender}\n{company}';

const D4 = 'Hi Dr. {last}. {hook} I work on patient education for longevity practices here in New York and would be glad to be connected. Not asking for anything, just following along.';

const D8 = 'Dr. {first} {last}\n{name}\n{neighborhood}, {borough}, NY\n\nWhat your patients forget within 48 hours of their visit\n\nYour patients leave {name} motivated. They paid for the time, they trust you, and they walk out planning to follow every word. Then life happens. Studies of patient recall have found that people forget somewhere between 40 and 80 percent of what they hear in a medical visit almost right away, and a good part of what they do remember is remembered wrong.\n\nFor a longevity practice that is a bigger problem than it sounds, because the results you promise depend on what patients do at home. With {serviceFull}, the thing patients most often lose track of is {forget}. When that slips, they either call your front desk, guess, or quietly stop. The last one is the one that shows up months later as a membership that does not renew.\n\nThe fix is not more time in the room. It is a short, plain-language page that goes home with the patient, written in your voice and matched to the protocol they are actually on. Practices that do this well tend to get fewer confused calls in the first week and better follow-through by the first retest.\n\nI sent {pm} on your team a sample of what that page can look like. It is free to keep and use however you like.\n\n{sender}\n{company}\n(This mailer is SAMPLE output and has not been printed or mailed.)';

const D11 = 'Hi {pm},\n\nAs promised, here is the example. I wrote it the way a patient at {name} would read it at home after their first longevity assessment, so feel free to mark it up.\n\nAfter your first longevity assessment\n\nYou did a lot of testing today, and the full picture comes together over the next week or two. Your lab results usually arrive within 7 to 10 days. Dr. {last} will walk you through them at your follow-up, so there is no need to make sense of the numbers on your own before then.\n\nUntil that visit, keep eating, sleeping, and exercising the way you normally do. Big changes right now make it harder to see your real baseline. {serviceLine}\n\nIf anything feels off, or you have a question that cannot wait, {contact}.\n\nThat is the whole thing. Most practices hand something like this out at checkout. If you want a version built on your own protocols and branding, I am happy to put one together at no cost.\n\nBest,\n{sender}';

const D15 = 'Hi Dr. {last},\n\nOver the last couple of weeks I sent {pm} a take-home example for your assessment patients, and I mailed you a short note about what patients forget after a visit. I figured the next useful thing was to show you what this could look like for {name} specifically.\n\nSo I recorded a two minute video walking through a take-home program for your {service} patients, built around how your practice already works: https://video.longevity.example/{slug}\n\nIf it is not useful, no need to reply.\n\n{sender}\n\nLinkedIn message: Hi Dr. {last}, I recorded a two minute walkthrough of what take-home education could look like for your {service} patients at {name}. Here it is if you are curious: https://video.longevity.example/{slug}';

const D18 = 'Hi Dr. {last},\n\nI do not want to keep showing up in your inbox, so this is my last note for now. If patient education becomes a priority at {name} {close}, I would be glad to pick this back up.\n\nEither way, the take-home example I sent {pm} is yours to keep and use however you like.\n\nWishing you and the team a good rest of the year.\n\n{sender}';

const rows = [];
$input.all().forEach(function (item, idx) {
  const c = item.json;
  const service = primaryService(c);
  const v = {
    pm: c.practice_manager_first,
    name: c.name,
    first: c.founder_first,
    last: c.founder_last,
    neighborhood: c.neighborhood,
    borough: c.borough,
    service: SHORT[service] || service,
    serviceFull: service,
    obs: observation(c),
    hook: linkedinHook(c),
    forget: FORGET[service] || 'the specific next steps they agreed to',
    serviceLine: SERVICE_LINE[service] || ('If we talked about ' + service + ', the details will be part of your follow-up plan.'),
    contact: c.has_online_booking === 'yes' ? 'message the care team through the same portal you used to book' : 'call the front desk and they will get your message to the clinical team',
    close: closeContext(c),
    slug: c.slug,
    sender: SENDER,
    company: COMPANY
  };
  const founder = c.decision_maker + ' (' + c.decision_maker_role + ')';
  const pmLabel = c.practice_manager + ' (Practice Manager)';
  const cohort = c.tier === 'A' ? 'Week 1 cohort, sent first' : c.tier === 'B' ? 'Week 1 cohort, sent after Tier A' : 'Week 1 cohort, sent last';
  const touches = [
    { day: 1, channel: 'Email', recipient: pmLabel, address: c.contact_email, subject: fill(D1_SUBJECTS[idx % 3], v), body: fill(D1, v) },
    { day: 4, channel: 'LinkedIn connection note', recipient: founder, address: 'LinkedIn profile of ' + c.decision_maker, subject: '', body: fill(D4, v) },
    { day: 8, channel: 'Mailed one-pager', recipient: founder, address: c.name + ', ' + c.neighborhood + ', ' + c.borough + ', NY (SAMPLE address)', subject: 'What your patients forget within 48 hours of their visit', body: fill(D8, v) },
    { day: 11, channel: 'Email', recipient: pmLabel, address: c.contact_email, subject: 'The take-home example I mentioned', body: fill(D11, v) },
    { day: 15, channel: 'Email and LinkedIn message', recipient: founder, address: c.founder_email, subject: fill('A two minute video for {name}', v), body: fill(D15, v) },
    { day: 18, channel: 'Email', recipient: founder, address: c.founder_email, subject: 'Closing the loop', body: fill(D18, v) }
  ];
  touches.forEach(function (t, i) {
    rows.push({
      json: {
        data_label: 'SAMPLE, not sent',
        clinic_id: c.id,
        clinic_name: c.name,
        tier: c.tier,
        score: c.score,
        cohort: cohort,
        touch: i + 1,
        day: t.day,
        channel: t.channel,
        recipient: t.recipient,
        recipient_address: t.address,
        subject: t.subject,
        body: t.body
      }
    });
  });
});
return rows;

